package com.xyz.question_bank_management_system.modules.source.controller;
import com.xyz.question_bank_management_system.common.ApiResponse; import com.xyz.question_bank_management_system.modules.source.dto.*; import com.xyz.question_bank_management_system.modules.source.entity.*; import com.xyz.question_bank_management_system.modules.source.service.SourceEvidenceService; import com.xyz.question_bank_management_system.util.SecurityContextUtil; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.List;
@RestController @RequestMapping("/api/admin/knowledge-sources") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')") public class SourceEvidenceController { private final SourceEvidenceService service;
 @PostMapping(value="/documents",consumes="multipart/form-data") public ApiResponse<Long> upload(@RequestPart("file") MultipartFile file,@ModelAttribute SourceDocumentUploadRequest request){return ApiResponse.ok(service.uploadDocument(file,request,SecurityContextUtil.getUserId()));}
 @GetMapping("/documents") public ApiResponse<List<SourceDocument>> documents(){return ApiResponse.ok(service.documents());} @GetMapping("/documents/{id}/chunks") public ApiResponse<List<SourceChunk>> chunks(@PathVariable Long id){return ApiResponse.ok(service.chunks(id));}
 @PostMapping("/knowledge-points/{id}/evidence") public ApiResponse<Long> linkKnowledge(@PathVariable Long id,@RequestBody EvidenceLinkRequest req){return ApiResponse.ok(service.linkKnowledge(id,req,SecurityContextUtil.getUserId()));} @GetMapping("/knowledge-points/{id}/evidence") public ApiResponse<List<KnowledgeSource>> knowledgeEvidence(@PathVariable Long id){return ApiResponse.ok(service.knowledgeEvidence(id));}
 @PostMapping("/resources/{id}/evidence") public ApiResponse<Long> linkResource(@PathVariable Long id,@RequestBody EvidenceLinkRequest req){return ApiResponse.ok(service.linkResource(id,req));} @GetMapping("/resources/{id}/evidence") public ApiResponse<List<ResourceSource>> resourceEvidence(@PathVariable Long id){return ApiResponse.ok(service.resourceEvidence(id));} }
